function berserk_fidget(self: EdictT): void {
  if ((self.monsterinfo.aiflags & MonsterAiFlagsT.AI_STAND_GROUND) !== 0n) return;
  else if (self.enemy !== null) return;
  if (frandom() > 0.15) return;

  M_SetAnimation(self, berserk_move_stand_fidget, false);
  gi.sound(self, SoundchanT.CHAN_WEAPON, sound_idle.index, 1, ATTN_IDLE, 0);
}

