// ---------------------------------------------------------------------------
// slam (jump attack) -- m_berserk.cpp:212-377
// ---------------------------------------------------------------------------

/** m_berserk.cpp:212-255 -- see file header's DEVIATIONS note on the
 *  persisting-mutation bug-for-bug behavior of `point`. */
function T_SlamRadiusDamage(pointIn: Vec3, inflictor: EdictT, attacker: EdictT, damage: number, kick: number, ignore: EdictT, radius: number, mod: ModT): void {
  const point = vec3(pointIn[0], pointIn[1], pointIn[2]); // by-value copy -- C++ mutates its own local across iterations
  let ent: EdictT | null = null;

  while ((ent = findradius(ent, inflictor.s.origin, radius * 2.0)) !== null) {
    if (ent === ignore) continue;
    if (!ent.takedamage) continue;
    if (!CanDamage(ent, inflictor)) continue;
    // don't hit players in mid air
    if (ent.client !== null && ent.groundentity === null) continue;

    const v = vec3_sub(closest_point_to_box(point, vec3_add(ent.s.origin, ent.mins), vec3_add(ent.s.origin, ent.maxs)), point);

    // calculate contribution amount
    const amount0 = Math.min(1.0, 1.0 - vec3_length(v) / radius);

    // too far away
    if (amount0 <= 0.0) continue;

    const amount = amount0 * amount0;

    // damage & kick are exponentially scaled
    const points = Math.max(1.0, damage * amount);

    const dir = vec3_normalized(vec3_sub(ent.s.origin, point));

    // keep the point at their feet so they always get knocked up -- mutates
    // `point` for THIS and every subsequent iteration, see file header
    point[2] = ent.absmin[2];

    T_Damage(ent, inflictor, attacker, dir, point, dir, Math.trunc(points), Math.trunc(kick * amount), DamageflagsT.DAMAGE_RADIUS, mod);

    if (ent.client !== null) ent.velocity[2] = Math.max(270.0, ent.velocity[2]);
  }
}

function berserk_attack_slam(self: EdictT): void {
  gi.sound(self, SoundchanT.CHAN_WEAPON, sound_thud.index, 1, ATTN_NORM, 0);
  gi.sound(self, SoundchanT.CHAN_AUTO, sound_explod.index, 0.75, ATTN_NORM, 0);
  gi.WriteByte(ServerCommandT.svc_temp_entity);
  gi.WriteByte(KexTempEventT.TE_BERSERK_SLAM);
  const { forward: f, right: r } = angleVectorsFR(self.s.angles);
  const start = M_ProjectFlashSource(self, vec3(20.0, -14.3, -21.0), f, r);
  const tr = giTraceline(self.s.origin, start, self, MASK_SOLID);
  gi.WritePosition(tr.endpos);
  gi.WriteDir(vec3(0.0, 0.0, 1.0));
  gi.multicast(tr.endpos, KexMulticastT.MULTICAST_PHS, false);
  self.gravity = 1.0;
  self.velocity = vec3(0, 0, 0);
  self.flags |= EntFlagsT.FL_KILL_VELOCITY;

  T_SlamRadiusDamage(tr.endpos, self, self, 8, 300.0, self, 165, MOD_UNKNOWN);
}

const berserk_jump_touch = RegisterTouch("berserk_jump_touch", (self: EdictT, _other: EdictT, _tr: KexTraceT, _otherTouchingSelf: boolean): void => {
  if (self.health <= 0) {
    self.touch = null;
    return;
  }

  if (self.groundentity !== null) {
    self.s.frame = FRAME_slam18;

    if (self.touch !== null) berserk_attack_slam(self);

    self.touch = null;
  }
});

function berserk_high_gravity(self: EdictT): void {
  if (self.velocity[2] < 0) self.gravity = 2.25 * (800.0 / level.gravity);
  else self.gravity = 5.25 * (800.0 / level.gravity);
}

function berserk_jump_takeoff(self: EdictT): void {
  if (self.enemy === null) return;

  // immediately turn to where we need to go
  const length = vec3_length(vec3_sub(self.s.origin, self.enemy.s.origin));
  const fwd_speed = length * 1.95;
  const dirOut: Vec3 = vec3(0, 0, 0);
  PredictAim(self, self.enemy, self.s.origin, fwd_speed, false, 0.0, dirOut, null);
  self.s.angles[1] = vectoyaw(dirOut);
  const forward = vec3(0, 0, 0);
  AngleVectors(self.s.angles, forward, null, null);
  self.s.origin[2] += 1;
  self.velocity = vec3_muls(forward, fwd_speed);
  self.velocity[2] = 450;
  self.groundentity = null;
  self.monsterinfo.aiflags |= MonsterAiFlagsT.AI_DUCKED;
  self.monsterinfo.attack_finished = Gtime_add(level.time, Gtime_from_sec(3));
  self.touch = berserk_jump_touch;
  berserk_high_gravity(self);
}

function berserk_check_landing(self: EdictT): void {
  berserk_high_gravity(self);

  if (self.groundentity !== null) {
    self.monsterinfo.attack_finished = GTIME_ZERO;
    if (self.monsterinfo.unduck !== null) self.monsterinfo.unduck(self);
    self.s.frame = FRAME_slam18;
    if (self.touch !== null) {
      berserk_attack_slam(self);
      self.touch = null;
    }
    self.flags &= ~EntFlagsT.FL_KILL_VELOCITY;
    return;
  }

  if (level.time > self.monsterinfo.attack_finished) self.monsterinfo.nextframe = FRAME_slam3;
  else self.monsterinfo.nextframe = FRAME_slam5;
}

