// ---------------------------------------------------------------------------
// melee dispatch + run-attack (charge-while-running) chain
// ---------------------------------------------------------------------------

export const berserk_melee = RegisterMonsterinfoMelee("berserk_melee", (self: EdictT): void => {
  if (self.monsterinfo.melee_debounce_time > level.time) {
    return;
    // if we're *almost* ready to land down the hammer from run-attack
    // don't switch us
  } else if (self.monsterinfo.active_move === berserk_move_run_attack1 && self.s.frame >= FRAME_r_att13) {
    self.monsterinfo.attack_state = MonsterAttackStateT.AS_STRAIGHT;
    self.monsterinfo.attack_finished = GTIME_ZERO;
    return;
  }

  monster_done_dodge(self);

  if (brandom()) M_SetAnimation(self, berserk_move_attack_spike, false);
  else M_SetAnimation(self, berserk_move_attack_club, false);
});

function berserk_run_attack_speed(self: EdictT): void {
  if (self.enemy !== null && range_to(self, self.enemy) < MELEE_DISTANCE) {
    self.monsterinfo.nextframe = self.s.frame + 6;
    monster_done_dodge(self);
  }
}

function berserk_run_swing(self: EdictT): void {
  berserk_swing(self);
  self.monsterinfo.melee_debounce_time = Gtime_add(level.time, Gtime_from_sec(0.6));

  if (self.monsterinfo.attack_state === MonsterAttackStateT.AS_SLIDING) {
    self.monsterinfo.attack_state = MonsterAttackStateT.AS_STRAIGHT;
    monster_done_dodge(self);
  }
}

function berserk_run_attack1_frame1(self: EdictT): void {
  berserk_run_attack_speed(self);
  monster_footstep(self);
}
function berserk_run_attack1_frame3(self: EdictT): void {
  berserk_run_attack_speed(self);
  monster_done_dodge(self);
}
function berserk_run_attack1_frame4(self: EdictT): void {
  berserk_run_attack_speed(self);
  monster_footstep(self);
}

