export const berserk_attack = RegisterMonsterinfoAttack("berserk_attack", (self: EdictT): void => {
  if (self.enemy === null) return;

  if (self.monsterinfo.melee_debounce_time <= level.time && range_to(self, self.enemy) < MELEE_DISTANCE) {
    berserk_melee(self);
    // only jump if they are far enough away for it to make sense (otherwise
    // it gets annoying to have them keep hopping over and over again)
  } else if (!SpawnFlags_has(self.spawnflags, SPAWNFLAG_BERSERK_NOJUMPING) && self.timestamp < level.time && brandom() && range_to(self, self.enemy) > 150.0) {
    M_SetAnimation(self, berserk_move_attack_strike, false);
    // don't do this for a while, otherwise we just keep doing it
    gi.sound(self, SoundchanT.CHAN_WEAPON, sound_jump.index, 1, ATTN_NORM, 0);
    self.timestamp = Gtime_add(level.time, Gtime_from_sec(5));
  } else if (self.monsterinfo.active_move === berserk_move_run1 && range_to(self, self.enemy) <= RANGE_NEAR) {
    M_SetAnimation(self, berserk_move_run_attack1, false);
    self.monsterinfo.nextframe = FRAME_r_att1 + (self.s.frame - FRAME_run1) + 1;
  }
});

