export const berserk_pain: PainFn = RegisterPain("berserk_pain", (self: EdictT, _other: EdictT, _kick: number, damage: number, mod: ModT): void => {
  // if we're jumping, don't pain
  if (self.monsterinfo.active_move === berserk_move_jump || self.monsterinfo.active_move === berserk_move_jump2 || self.monsterinfo.active_move === berserk_move_attack_strike) {
    return;
  }

  if (level.time < self.pain_debounce_time) return;

  self.pain_debounce_time = Gtime_add(level.time, Gtime_from_sec(3));
  gi.sound(self, SoundchanT.CHAN_VOICE, sound_pain.index, 1, ATTN_NORM, 0);

  if (!M_ShouldReactToPain(self, mod)) return; // no pain anims in nightmare

  monster_done_dodge(self);

  if (damage <= 50 || frandom() < 0.5) M_SetAnimation(self, berserk_move_pain1, false);
  else M_SetAnimation(self, berserk_move_pain2, false);
});

export const berserk_setskin = RegisterMonsterinfoSetskin("berserk_setskin", (self: EdictT): void => {
  if (self.health < self.max_health / 2) self.s.skinnum = 1;
  else self.s.skinnum = 0;
});

