export const berserk_die: DieFn = RegisterDie("berserk_die", (self: EdictT, _inflictor: EdictT, _attacker: EdictT, damage: number, _point: Vec3, mod: ModT): void => {
  if (M_CheckGib(self, mod)) {
    gi.sound(self, SoundchanT.CHAN_VOICE, gi.soundindex("misc/udeath.wav"), 1, ATTN_NORM, 0);

    self.s.skinnum = 0;

    ThrowGibs(self, damage, [
      { count: 2, gibname: "models/objects/gibs/bone/tris.md2" },
      { count: 3, gibname: "models/objects/gibs/sm_meat/tris.md2" },
      { count: 1, gibname: "models/objects/gibs/gear/tris.md2" },
      { gibname: "models/monsters/berserk/gibs/chest.md2", type: GibTypeT.GIB_SKINNED },
      { gibname: "models/monsters/berserk/gibs/hammer.md2", type: GibTypeT.GIB_SKINNED | GibTypeT.GIB_UPRIGHT },
      { gibname: "models/monsters/berserk/gibs/thigh.md2", type: GibTypeT.GIB_SKINNED },
      { gibname: "models/monsters/berserk/gibs/head.md2", type: GibTypeT.GIB_HEAD | GibTypeT.GIB_SKINNED },
    ]);
    self.deadflag = true;
    return;
  }

  if (self.deadflag) return;

  gi.sound(self, SoundchanT.CHAN_VOICE, sound_die.index, 1, ATTN_NORM, 0);
  self.deadflag = true;
  self.takedamage = true;

  if (damage >= 50) M_SetAnimation(self, berserk_move_death1, false);
  else M_SetAnimation(self, berserk_move_death2, false);
});

// ---------------------------------------------------------------------------
// PGM: jump-over-obstacle + blocked/sidestep/duck
// ---------------------------------------------------------------------------

function berserk_jump_now(self: EdictT): void {
  const forward = vec3(0, 0, 0);
  const up = vec3(0, 0, 0);
  AngleVectors(self.s.angles, forward, null, up);
  self.velocity = vec3_add(self.velocity, vec3_muls(forward, 100));
  self.velocity = vec3_add(self.velocity, vec3_muls(up, 300));
}

function berserk_jump2_now(self: EdictT): void {
  const forward = vec3(0, 0, 0);
  const up = vec3(0, 0, 0);
  AngleVectors(self.s.angles, forward, null, up);
  self.velocity = vec3_add(self.velocity, vec3_muls(forward, 150));
  self.velocity = vec3_add(self.velocity, vec3_muls(up, 400));
}

function berserk_jump_wait_land(self: EdictT): void {
  if (self.groundentity === null) {
    self.monsterinfo.nextframe = self.s.frame;

    if (monster_jump_finished(self)) self.monsterinfo.nextframe = self.s.frame + 1;
  } else {
    self.monsterinfo.nextframe = self.s.frame + 1;
  }
}

