function berserk_jump(self: EdictT, result: BlockedJumpResultT): void {
  if (self.enemy === null) return;

  if (result === BlockedJumpResultT.JUMP_JUMP_UP) M_SetAnimation(self, berserk_move_jump2, false);
  else M_SetAnimation(self, berserk_move_jump, false);
}

export const berserk_blocked = RegisterMonsterinfoBlocked("berserk_blocked", (self: EdictT, dist: number): boolean => {
  const result = blocked_checkjump(self, dist);
  if (result !== BlockedJumpResultT.NO_JUMP) {
    if (result !== BlockedJumpResultT.JUMP_TURN) berserk_jump(self, result);

    return true;
  }

  if (blocked_checkplat(self, dist)) return true;

  return false;
});

export const berserk_sidestep = RegisterMonsterinfoSidestep("berserk_sidestep", (self: EdictT): boolean => {
  // if we're jumping or in long pain, don't dodge
  if (
    self.monsterinfo.active_move === berserk_move_jump ||
    self.monsterinfo.active_move === berserk_move_jump2 ||
    self.monsterinfo.active_move === berserk_move_attack_strike ||
    self.monsterinfo.active_move === berserk_move_pain2
  ) {
    return false;
  }

  if (self.monsterinfo.active_move !== berserk_move_run1) M_SetAnimation(self, berserk_move_run1, false);

  return true;
});

