export const berserk_duck = RegisterMonsterinfoDuck("berserk_duck", (self: EdictT, _eta: GTime): boolean => {
  // berserk only dives forward, and very rarely
  if (frandom() >= 0.05) return false;

  // if we're jumping, don't dodge
  if (self.monsterinfo.active_move === berserk_move_jump || self.monsterinfo.active_move === berserk_move_jump2) return false;

  M_SetAnimation(self, berserk_move_duck2, false);

  return true;
});

// ---------------------------------------------------------------------------
// SP_monster_berserk (m_berserk.cpp:769-836)
// ---------------------------------------------------------------------------

/*QUAKED monster_berserk (1 .5 0) (-16 -16 -24) (16 16 32) Ambush Trigger_Spawn Sight
 */
export function SP_monster_berserk(self: EdictT): void {
  if (!M_AllowSpawn(self)) {
    G_FreeEdict(self);
    return;
  }

  // pre-caches
  assignSound(sound_pain, "berserk/berpain2.wav");
  assignSound(sound_die, "berserk/berdeth2.wav");
  assignSound(sound_idle, "berserk/beridle1.wav");
  assignSound(sound_idle2, "berserk/idle.wav");
  assignSound(sound_punch, "berserk/attack.wav");
  assignSound(sound_search, "berserk/bersrch1.wav");
  assignSound(sound_sight, "berserk/sight.wav");
  assignSound(sound_thud, "mutant/thud1.wav");
  assignSound(sound_explod, "world/explod2.wav");
  assignSound(sound_jump, "berserk/jump.wav");

  self.s.modelindex = gi.modelindex("models/monsters/berserk/tris.md2");

  gi.modelindex("models/monsters/berserk/gibs/head.md2");
  gi.modelindex("models/monsters/berserk/gibs/chest.md2");
  gi.modelindex("models/monsters/berserk/gibs/hammer.md2");
  gi.modelindex("models/monsters/berserk/gibs/thigh.md2");

  self.mins = vec3(-16, -16, -24);
  self.maxs = vec3(16, 16, 32);
  self.movetype = MovetypeT.MOVETYPE_STEP;
  self.solid = SolidT.SOLID_BBOX;

  self.health = Math.trunc(240 * st.health_multiplier);
  self.gib_health = -60;
  self.mass = 250;

  self.pain = berserk_pain;
  self.die = berserk_die;

  self.monsterinfo.stand = berserk_stand;
  self.monsterinfo.walk = berserk_walk;
  self.monsterinfo.run = berserk_run;
  // pmm
  self.monsterinfo.dodge = M_MonsterDodge;
  self.monsterinfo.duck = berserk_duck;
  self.monsterinfo.unduck = monster_duck_up;
  self.monsterinfo.sidestep = berserk_sidestep;
  self.monsterinfo.blocked = berserk_blocked; // PGM
  // pmm
  self.monsterinfo.attack = berserk_attack;
  self.monsterinfo.melee = berserk_melee;
  self.monsterinfo.sight = berserk_sight;
  self.monsterinfo.search = berserk_search;
  self.monsterinfo.setskin = berserk_setskin;

  M_SetAnimation(self, berserk_move_stand, false);
  self.monsterinfo.scale = MODEL_SCALE;

  self.monsterinfo.combat_style = CombatStyleT.COMBAT_MELEE;
  self.monsterinfo.can_jump = !SpawnFlags_has(self.spawnflags, SPAWNFLAG_BERSERK_NOJUMPING);
  self.monsterinfo.drop_height = 256;
  self.monsterinfo.jump_height = 40;

  gi.linkentity(self);

  walkmonster_start(self);
}
